// Telugu numerology texts. Keys match numerologyTextsEn in numerology_texts.dart.
const numerologyTextsTe = <String, String>{
  // What each number type represents
  'type.lifePath': 'జీవన మార్గ సంఖ్య పూర్తి పుట్టిన తేదీ నుండి వస్తుంది. సంప్రదాయం దీనిని జీవితకాలపు ప్రధాన ఇతివృత్తంగా చదువుతుంది: మళ్ళీ మళ్ళీ ఎదురయ్యే పాఠాలు, ఆసక్తులు, దిశ.',
  'type.birthday': 'పుట్టినరోజు సంఖ్య కేవలం నెలలోని తేదీ నుండి వస్తుంది. మీరు జీవన మార్గానికి జోడించే ఒక ప్రత్యేక ప్రతిభగా లేదా పని చేసే తీరుగా దీనిని చదువుతారు.',
  'type.mulank': 'మూల సంఖ్య (మూలాంక్) పుట్టిన రోజు (తేదీ) నుండి వస్తుంది. భారతీయ సంఖ్యాశాస్త్రం దీనిని మీ ప్రాథమిక స్వభావంగా చదువుతుంది: రోజువారీగా మీరు ఎలా ఆలోచిస్తారు, ఎలా ప్రవర్తిస్తారు.',
  'type.bhagyank': 'భాగ్య సంఖ్య (భాగ్యాంక్) పుట్టిన తేదీలోని అన్ని అంకెల నుండి వస్తుంది. భారతీయ సంఖ్యాశాస్త్రం దీనిని జీవితపు విస్తృత దిశగా, దానితో పాటు వచ్చే అవకాశాల తీరుగా చదువుతుంది.',
  'type.expression': 'వ్యక్తీకరణ సంఖ్య పూర్తి పేరులోని ప్రతి అక్షరం నుండి వస్తుంది. దీనిని మీ సహజ సామర్థ్యాలుగా, పనిలోనూ జీవితంలోనూ వాటిని మీరు వ్యక్తపరిచే తీరుగా చదువుతారు.',
  'type.soulUrge': 'ఆత్మ సంఖ్య పేరులోని అచ్చుల నుండి వస్తుంది. దీనిని అంతర్గత ప్రేరణగా చదువుతారు: మీరు బయటికి చూపించకపోయినా, లోలోపల నిజంగా కోరుకునేది.',
  'type.personality': 'వ్యక్తిత్వ సంఖ్య పేరులోని హల్లుల నుండి వస్తుంది. మీరు కలిగించే మొదటి అభిప్రాయంగా, ఇతరులు సాధారణంగా మిమ్మల్ని ఎలా చూస్తారో దానిగా దీనిని చదువుతారు.',
  'type.chaldeanName': 'కాల్డియన్ నామ సంఖ్య అక్షరాల ధ్వని ఆధారంగా రూపొందిన పాత అక్షర పట్టికను ఉపయోగిస్తుంది. అందరూ మిమ్మల్ని పిలిచే పేరు యొక్క మొత్తం ప్రకంపనగా దీనిని చదువుతారు.',

  // Fuller meanings: strengths, challenges, practical guidance
  'num.1.strengths': 'చొరవ, స్వతంత్రత, పనులు ప్రారంభించి నాయకత్వం వహించే ధైర్యం.',
  'num.1.challenges': 'అసహనం, మొండితనం లేదా సహాయం స్వీకరించడానికి వెనుకాడటం కనిపించవచ్చు.',
  'num.1.guidance': 'కొత్త పనుల్లో ముందుండండి, కానీ నిర్ణయించే ముందు ఇతరుల మాట వినండి, ఘనతను పంచుకోండి.',
  'num.2.strengths': 'నేర్పు, ఓపిక, ఇతరుల పట్ల సున్నితత్వం, సహకరించే స్వభావం.',
  'num.2.challenges': 'అతి సున్నితత్వం, నిర్ణయం తీసుకోలేకపోవడం లేదా అందరినీ సంతోషపెట్టాలనే అతి ఆత్రుత కనిపించవచ్చు.',
  'num.2.guidance': 'భాగస్వామ్యాలు, బృంద కృషి మీకు సరిపోతాయి; అవసరమైనప్పుడు ప్రశాంతంగా "కాదు" అనడం సాధన చేయండి.',
  'num.3.strengths': 'సృజనాత్మకత, ఉల్లాసమైన వ్యక్తీకరణ, మాటలతోనూ మనుషులతోనూ నేర్పు.',
  'num.3.challenges': 'శక్తి చాలా ఆసక్తుల మధ్య చెదిరిపోవచ్చు; రోజువారీ దినచర్యను తప్పించుకోవచ్చు.',
  'num.3.guidance': 'పూర్తి చేయడానికి ఒకటి రెండు పనులను ఎంచుకోండి, ఇతరులను ప్రోత్సహించడానికి మీ మాటను ఉపయోగించండి.',
  'num.4.strengths': 'విశ్వసనీయత, క్రమపద్ధతి, కష్టపడే తత్వం, ఆచరణాత్మకంగా సమస్యలను పరిష్కరించే నేర్పు.',
  'num.4.challenges': 'కఠినంగా ఉండటం, అతిగా పని చేయడం లేదా ఆకస్మిక మార్పులను ప్రతిఘటించడం కనిపించవచ్చు.',
  'num.4.guidance':
      'అంచెలంచెలుగా నిర్మించండి, కొంత సరళత ఉంచుకోండి, పనికి ఇచ్చినంత ప్రాధాన్యం విశ్రాంతికీ ఇచ్చి ప్రణాళిక వేసుకోండి.',
  'num.5.strengths': 'జిజ్ఞాస, పరిస్థితులకు అనుగుణంగా మారే గుణం, వేగవంతమైన ఆలోచన, సంభాషణా నైపుణ్యం.',
  'num.5.challenges': 'చంచలత్వం, ఆవేశపూరిత నిర్ణయాలు, ఒక బాధ్యతకు కట్టుబడి ఉండటంలో కష్టం.',
  'num.5.guidance': 'మార్పును స్వాగతించండి కానీ కొన్ని స్థిరమైన అలవాట్లను కొనసాగించండి; పెద్ద సాహసాలకు దిగే ముందు రెండుసార్లు ఆలోచించండి.',
  'num.6.strengths': 'శ్రద్ధ, బాధ్యత, సౌందర్య దృష్టి, ఇంట్లో సామరస్యం.',
  'num.6.challenges': 'ఇతరుల కోసం మరీ ఎక్కువ భారం మోయడం, ఆందోళన చెందడం లేదా నియంత్రించాలని ప్రయత్నించడం కనిపించవచ్చు.',
  'num.6.guidance':
      'మిమ్మల్ని మీరు నిర్లక్ష్యం చేసుకోకుండా ఇతరులకు సేవ చేయండి; వారి సమస్యలను వారే పరిష్కరించుకోనివ్వండి.',
  'num.7.strengths': 'లోతైన ఆలోచన, పరిశోధన, అంతర్బుద్ధి, సుసంపన్నమైన అంతర్జీవితం.',
  'num.7.challenges': 'అందరికీ దూరంగా ఉండిపోవడం, అతిగా ఆలోచించడం లేదా ఇతరులను నమ్మడంలో కష్టం కనిపించవచ్చు.',
  'num.7.guidance': 'అధ్యయనానికీ ప్రశాంతతకూ సమయం కేటాయించండి, మీ ఆలోచనలను నమ్మకమైన కొద్దిమందితో పంచుకోండి.',
  'num.8.strengths': 'క్రమశిక్షణ, ఆశయం, ఓపిక, వనరులను నిర్వహించే నైపుణ్యం.',
  'num.8.challenges': 'అతి గంభీరత, పనిపైనే దృష్టి, లేదా ఫలితాలు నెమ్మదిగా వస్తున్నాయనే భావన కలగవచ్చు.',
  'num.8.guidance': 'స్థిరమైన కృషికి కాలక్రమంలో ఫలితం దక్కుతుందని సంప్రదాయం చెబుతుంది; పనితో పాటు కుటుంబం, ఆరోగ్యాన్నీ సమతుల్యం చేసుకోండి.',
  'num.9.strengths': 'కరుణ, ధైర్యం, ఉదారత, విశాల దృక్పథం.',
  'num.9.challenges': 'అసహనం, త్వరగా కోపం రావడం, లేదా అలసిపోయేంత వరకు ఇచ్చేయడం కనిపించవచ్చు.',
  'num.9.guidance':
      'మీకు ముఖ్యమైన లక్ష్యాల వైపు శక్తిని మళ్ళించండి; ప్రారంభించినది పూర్తి చేయండి, హుందాగా వదిలిపెట్టడం నేర్చుకోండి.',
  'num.11.strengths': 'అంతర్బుద్ధి, స్ఫూర్తి, ఇతరులలో ఉత్సాహం నింపి వారిని ఉన్నతంగా నిలిపే సామర్థ్యం.',
  'num.11.challenges': 'నరాల ఒత్తిడి, ఆత్మసందేహం, తనపై తనకు అధిక అంచనాలు.',
  'num.11.guidance': 'ఆలోచనలను రోజువారీ ఆచరణలో నిలబెట్టండి; సాధారణ రోజుల్లో 2 యొక్క లక్షణాలు వర్తిస్తాయి.',
  'num.22.strengths': 'దూరదృష్టితో పాటు చిరకాలం నిలిచేవాటిని నిర్మించే ఆచరణాత్మక నైపుణ్యం.',
  'num.22.challenges': 'ఎంతో సాధించాలనే ఒత్తిడి; పెద్ద ప్రణాళికల భారంతో ఉక్కిరిబిక్కిరి అయినట్లు అనిపించవచ్చు.',
  'num.22.guidance': 'పెద్ద లక్ష్యాలను చిన్న అడుగులుగా విభజించండి; సాధారణ రోజుల్లో 4 యొక్క లక్షణాలు వర్తిస్తాయి.',
  'num.33.strengths': 'కరుణతో కూడిన బోధన, స్వస్థత చేకూర్చడం, ఇతరులకు సేవ.',
  'num.33.challenges': 'స్వీయ త్యాగం, ఇతరుల భారాలను మోయడం, పరిపూర్ణతావాదం.',
  'num.33.guidance': 'ఇతరులతో పాటు మిమ్మల్నీ చూసుకోండి; సాధారణ రోజుల్లో 6 యొక్క లక్షణాలు వర్తిస్తాయి.',

  // Mulank-Bhagyank pair
  'pair.intro': 'మూలాంక్ మీరు రోజువారీగా ఎలా ప్రవర్తిస్తారో చూపుతుంది; భాగ్యాంక్ జీవితపు విస్తృత దిశను చూపుతుంది. భారతీయ సంఖ్యాశాస్త్రం గ్రహాల సాంప్రదాయ సహజ (నైసర్గిక) మైత్రిని ఆధారంగా చేసుకుని వీటి అధిపతి గ్రహాలను పోలుస్తుంది.',
  'pair.same': 'రెండు సంఖ్యలకూ ఒకే గ్రహం, కాబట్టి దాని లక్షణాలు బలపడినట్లు సంప్రదాయంగా చదువుతారు: దాని బలాలు పెరుగుతాయి, దాని సాధారణ సవాళ్లు కూడా అలాగే పెరుగుతాయి.',
  'pair.friendly': 'అధిపతి గ్రహాలు సహజ మిత్రులు, కాబట్టి మీ స్వభావం (మూలాంక్), జీవిత దిశ (భాగ్యాంక్) ఒకదానికొకటి తోడ్పడతాయని సంప్రదాయం చదువుతుంది.',
  'pair.neutral': 'గ్రహాలు సమ సంబంధంలో ఉన్నాయి, లేదా ఒకదాన్ని మరొకటి వేర్వేరుగా పరిగణిస్తాయి, కాబట్టి సంప్రదాయం ఈ జంటను నిర్వహించదగినదిగా చదువుతుంది: రెండు ప్రభావాలు ఒకదానికొకటి పెద్దగా సహాయపడవు, అడ్డుపడవు.',
  'pair.challenging': 'సాంప్రదాయ పట్టికలో ఈ గ్రహాలు సహజ శత్రువులు, కాబట్టి స్వభావానికీ జీవిత దిశకూ మధ్య కొంత అంతర్గత ఉద్రిక్తత ఉండవచ్చని సంప్రదాయం సూచిస్తుంది. దీనిని చెడు సూచనగా కాకుండా, స్పృహతో సమతుల్యం చేసుకోవలసిన అంశంగా చదువుతారు.',
  'pair.nodesNote': 'రాహువు (4), కేతువు (7) సాంప్రదాయ మైత్రి పట్టికలో లేరు. ఈ యాప్ తర్వాతి కాలంలో ప్రచారంలోకి వచ్చిన ఒక సాధారణ పద్ధతిని ఉపయోగిస్తుంది (రాహువు: మిత్రులు బుధుడు, శుక్రుడు, శని; కేతువు: మిత్రులు కుజుడు, శుక్రుడు, శని); ఈ విషయంలో వివిధ శాఖల మధ్య భేదాలు ఉన్నాయి.',

  // Lo Shu grid
  'loshu.intro': 'లో షు చతురస్రం ఒక ప్రాచీన చైనా మాయా చతురస్రం; దీనిలో ప్రతి అడ్డు వరుస, నిలువు వరుస, కర్ణం మొత్తం 15 అవుతుంది. పుట్టిన తేదీలోని ప్రతి అంకెను దాని గడిలో ఉంచుతారు (అమరిక 4-9-2 / 3-5-7 / 8-1-6); సున్నాలను పరిగణించరు.',
  'loshu.indianNote': 'సాధారణ భారతీయ పద్ధతిలో భాగ్యాంక్‌ను కూడా కలుపుతారు; పుట్టిన రోజు 1-9, 10, 20 లేదా 30 అయితే తప్ప మూలాంక్‌నూ కలుపుతారు (ఆ సందర్భాల్లో అది ఇప్పటికే చతురస్రంలో ఉంటుంది). కేవలం తేదీతో ఏర్పడే చతురస్రాన్ని చూడాలంటే దీన్ని ఆపివేయండి.',
  'loshu.missing.1': '1 లేదు: మిమ్మల్ని, మీ భావాలను వ్యక్తపరచడానికి స్పృహతో ప్రయత్నించవలసి రావచ్చు.',
  'loshu.missing.2': '2 లేదు: ఓపికను, ఇతరుల పట్ల సున్నితత్వాన్ని పెంపొందించుకోవలసి రావచ్చు.',
  'loshu.missing.3': '3 లేదు: ఊహాశక్తికీ, మీ ఆలోచనలపై నమ్మకానికీ ప్రోత్సాహం అవసరం కావచ్చు.',
  'loshu.missing.4': '4 లేదు: క్రమం, క్రమశిక్షణ, దినచర్యలపై ప్రత్యేక శ్రద్ధ అవసరం కావచ్చు.',
  'loshu.missing.5': '5 లేదు: భావోద్వేగ సమతుల్యత, స్థిరమైన ఏకాగ్రతకు సాధన అవసరం కావచ్చు.',
  'loshu.missing.6': '6 లేదు: ఇల్లు, కుటుంబ బాధ్యతలు, సౌకర్యాలపై మరింత శ్రద్ధ అవసరం కావచ్చు.',
  'loshu.missing.7': '7 లేదు: పాఠాలు తరచుగా అనుభవం ద్వారానే వస్తాయి; ఆత్మపరిశీలనకు సమయం కేటాయించడం సహాయపడుతుంది.',
  'loshu.missing.8': '8 లేదు: వివరాలపై శ్రద్ధకు, జాగ్రత్తగా డబ్బు నిర్వహించడానికి ప్రయత్నం అవసరం కావచ్చు.',
  'loshu.missing.9': '9 లేదు: ఆశయాన్ని, విస్తృత లక్ష్యాన్ని స్పృహతో పెంపొందించుకోవలసి రావచ్చు.',
  'loshu.repeat.1.2': '1 రెండుసార్లు: సంప్రదాయంగా సమతుల్యమైన, స్పష్టమైన స్వీయ వ్యక్తీకరణగా చదువుతారు.',
  'loshu.repeat.1.3': '1 మూడు లేదా అంతకంటే ఎక్కువసార్లు: ఎక్కువగా మాట్లాడవచ్చు, లేదా లోతైన భావాలను మాటల్లో పెట్టడం కష్టంగా అనిపించవచ్చు.',
  'loshu.repeat.2.2': '2 రెండుసార్లు: బలమైన అంతర్బుద్ధి, సున్నితత్వం; మనుషులను బాగా అంచనా వేస్తారు.',
  'loshu.repeat.2.3':
      '2 మూడు లేదా అంతకంటే ఎక్కువసార్లు: సులభంగా నొచ్చుకోవచ్చు; మీ భావోద్వేగ శక్తిని కాపాడుకోవడం సహాయపడుతుంది.',
  'loshu.repeat.3.2': '3 రెండుసార్లు: గొప్ప ఊహాశక్తి, సృజనాత్మకమైన, చురుకైన మనసు.',
  'loshu.repeat.3.3': '3 మూడు లేదా అంతకంటే ఎక్కువసార్లు: ఆలోచనలు చెదిరిపోవచ్చు లేదా ఆందోళనగా మారవచ్చు; విషయాలను రాసుకోవడం సహాయపడుతుంది.',
  'loshu.repeat.4.2': '4 రెండుసార్లు: చాలా క్రమబద్ధంగా, కష్టపడి పనిచేస్తారు; ఆచరణాత్మక నైపుణ్యాల్లో నేర్పు.',
  'loshu.repeat.4.3':
      '4 మూడు లేదా అంతకంటే ఎక్కువసార్లు: కఠినంగా మారవచ్చు లేదా భౌతిక విషయాలపై మరీ ఎక్కువ దృష్టి పెట్టవచ్చు.',
  'loshu.repeat.5.2': '5 రెండుసార్లు: బలమైన ఉత్సాహం, దృఢ సంకల్పం.',
  'loshu.repeat.5.3': '5 మూడు లేదా అంతకంటే ఎక్కువసార్లు: తొందరపడి ప్రవర్తించవచ్చు లేదా మాట్లాడవచ్చు; స్పందించే ముందు ఒక్క క్షణం ఆగడం సహాయపడుతుంది.',
  'loshu.repeat.6.2': '6 రెండుసార్లు: ఇల్లు, కుటుంబం పట్ల లోతైన శ్రద్ధ.',
  'loshu.repeat.6.3':
      '6 మూడు లేదా అంతకంటే ఎక్కువసార్లు: ప్రియమైనవారి గురించి ఆందోళన చెందవచ్చు లేదా వారిని అతిగా కాపాడాలని చూడవచ్చు.',
  'loshu.repeat.7.2':
      '7 రెండుసార్లు: అనుభవం నుండి లోతుగా నేర్చుకుంటారు; అధ్యయనం, అంతర్గత ప్రశ్నల వైపు ఆకర్షితులవుతారు.',
  'loshu.repeat.7.3': '7 మూడు లేదా అంతకంటే ఎక్కువసార్లు: జీవిత పాఠాలు కొన్నిసార్లు భారంగా అనిపించవచ్చు; విశ్రాంతి, ఇతరుల తోడ్పాటు ముఖ్యం.',
  'loshu.repeat.8.2': '8 రెండుసార్లు: క్రమపద్ధతి, వివరాలపై శ్రద్ధ, విశ్వసనీయత.',
  'loshu.repeat.8.3': '8 మూడు లేదా అంతకంటే ఎక్కువసార్లు: చంచలంగా మారవచ్చు లేదా పరిపూర్ణతావాదం పెరగవచ్చు.',
  'loshu.repeat.9.2': '9 రెండుసార్లు: ఆదర్శవాదం, ఆశయం, త్వరగా అర్థం చేసుకునే గుణం.',
  'loshu.repeat.9.3': '9 మూడు లేదా అంతకంటే ఎక్కువసార్లు: ఇతరుల పట్ల విమర్శనాత్మకంగా లేదా అసహనంగా మారవచ్చు.',
  'loshu.plane.mental.name': 'మానసిక తలం',
  'loshu.plane.mental.meaning':
      'పై అడ్డు వరుస పూర్తి: సంప్రదాయంగా మంచి జ్ఞాపకశక్తి, విశ్లేషణ, ప్రణాళికతో ముడిపడి ఉంది.',
  'loshu.plane.emotional.name': 'భావోద్వేగ తలం',
  'loshu.plane.emotional.meaning': 'మధ్య అడ్డు వరుస పూర్తి: సంప్రదాయంగా భావోద్వేగ లోతు, సహానుభూతితో ముడిపడి ఉంది.',
  'loshu.plane.practical.name': 'ఆచరణాత్మక తలం',
  'loshu.plane.practical.meaning':
      'కింది అడ్డు వరుస పూర్తి: సంప్రదాయంగా ఆచరణాత్మక నైపుణ్యం, పనులను పూర్తి చేయడంతో ముడిపడి ఉంది.',
  'loshu.plane.thought.name': 'ఆలోచనా తలం',
  'loshu.plane.thought.meaning': 'ఎడమ నిలువు వరుస పూర్తి: సంప్రదాయంగా ఆలోచనలు, ప్రణాళిక, వ్యవస్థీకరణతో ముడిపడి ఉంది.',
  'loshu.plane.will.name': 'సంకల్ప తలం',
  'loshu.plane.will.meaning': 'మధ్య నిలువు వరుస పూర్తి: సంప్రదాయంగా దృఢ సంకల్పం, పట్టుదలతో ముడిపడి ఉంది.',
  'loshu.plane.action.name': 'కార్య తలం',
  'loshu.plane.action.meaning': 'కుడి నిలువు వరుస పూర్తి: సంప్రదాయంగా ఆలోచనలను ఆచరణలో పెట్టడంతో ముడిపడి ఉంది.',
  'loshu.plane.golden.name': 'స్వర్ణ తలం',
  'loshu.plane.golden.meaning': '4-5-6 కర్ణం పూర్తి: కొందరు భారతీయ సంఖ్యాశాస్త్రజ్ఞులు దీనిని "స్వర్ణ యోగం" అని పిలుస్తారు, స్థిరమైన కృషి పురోగతిగా మారడంగా చదువుతారు.',
  'loshu.plane.silver.name': 'రజత తలం',
  'loshu.plane.silver.meaning': '2-5-8 కర్ణం పూర్తి: కొందరు భారతీయ సంఖ్యాశాస్త్రజ్ఞులు దీనిని "రజత యోగం" అని పిలుస్తారు, అంతర్బుద్ధి, ఆస్తి విషయాలతో ముడిపెడతారు.',

  // Chaldean compound numbers (Cheiro's tradition, in neutral words)
  'compound.intro': 'కీరో సంప్రదాయంలో, కుదించక ముందు ఉన్న కాల్డియన్ మొత్తానికి (10-52) దానికంటూ ఒక అర్థం ఉంటుంది; దానిని ఏక అంకెతో కలిపి చదువుతారు.',
  'compound.10':
      '"అదృష్ట చక్రం" అని పిలుస్తారు: గౌరవం, ఆత్మవిశ్వాసం, మలుపులుగా వచ్చే ఎత్తుపల్లాలు; అందరికీ తెలిసే పేరు.',
  'compound.11': 'దాగి ఉన్న అడ్డంకుల విషయంలో, ఎవరిని నమ్ముతారనే విషయంలో జాగ్రత్తగా ఉండమని సంప్రదాయం సూచిస్తుంది; విశ్వాసానికీ ఓపికకూ ప్రాధాన్యం ఇస్తుంది.',
  'compound.12':
      'ఇతరుల కోసం త్యాగంతో ముడిపడి ఉంది; ఇతరులకు సహాయం చేస్తూనే మీ సొంత ప్రయోజనాలను కాపాడుకోమని సంప్రదాయం సూచిస్తుంది.',
  'compound.13': 'మార్పు, పరివర్తన, ముగింపుల తర్వాత కొత్త ప్రారంభాలతో ముడిపడి ఉంది; వివేకంతో వినియోగించవలసిన శక్తి.',
  'compound.14': 'కదలిక, వ్యాపారం, మనుషులతో వ్యవహారాలు; ఊహాజనిత పెట్టుబడుల విషయంలో, ఇతరుల తీర్పుపై ఆధారపడటంలో జాగ్రత్తగా ఉండమని సంప్రదాయం సూచిస్తుంది.',
  'compound.15': 'ఆకర్షణ, వాక్చాతుర్యం, కళాత్మక ప్రతిభ; ఇతరుల నుండి సహాయం అందుతుంది. దీనిని నిజాయితీగా ఉపయోగించమని సంప్రదాయం చెబుతుంది.',
  'compound.16': 'ప్రణాళికల్లో లేదా హోదాలో ఆకస్మిక మార్పులతో ముడిపడి ఉంది; జాగ్రత్తగా ప్రణాళిక వేసుకోమని, వినయంగా ఉండమని సంప్రదాయం సూచిస్తుంది.',
  'compound.17': '"జ్ఞానుల నక్షత్రం" అని పిలుస్తారు: శాంతి, ప్రేమ, పరీక్షలను అధిగమించడం; గుర్తుండిపోయే పేరు.',
  'compound.18':
      'భౌతిక, ఆధ్యాత్మిక లక్ష్యాల మధ్య ఉద్రిక్తతతో ముడిపడి ఉంది; వివాదాల్లో జాగ్రత్తగా ఉండమని సంప్రదాయం సూచిస్తుంది.',
  'compound.19':
      '"స్వర్గపు రాకుమారుడు" అని పిలుస్తారు: ఆనందం, గౌరవం, విజయం; అత్యంత అనుకూలమైన సంఖ్యల్లో ఒకటిగా పరిగణిస్తారు.',
  'compound.20': '"మేలుకొలుపు" అని పిలుస్తారు: కొత్త లక్ష్యం, ప్రణాళికల వైపు పిలుపు; భౌతిక లాభం కంటే అంతర్గత ఎదుగుదలగానే ఎక్కువగా చదువుతారు.',
  'compound.21': '"జ్ఞానుల కిరీటం" అని పిలుస్తారు: పురోగతి, గుర్తింపు, తరచుగా సుదీర్ఘ కృషి తర్వాత.',
  'compound.22': 'భ్రమలు, అతి నమ్మకం, ఇతరుల నుండి వచ్చే సరికాని సలహాల విషయంలో జాగ్రత్తగా ఉండమని సంప్రదాయం సూచిస్తుంది; మీ సొంత వివేచనను నిలుపుకోండి.',
  'compound.23': '"సింహపు రాజ నక్షత్రం" అని పిలుస్తారు: ప్రణాళికల్లో విజయం, అధికారంలో ఉన్నవారి నుండి సహాయం.',
  'compound.24': 'అనుకూలమైనది: ఉన్నత స్థానాల్లో ఉన్నవారి నుండి సహాయం, ప్రేమలోనూ భాగస్వామ్యంలోనూ ఆత్మీయత.',
  'compound.25': 'అనుభవం, పరిశీలన ద్వారా లభించే బలం; మొదట్లో పరీక్షలు, తర్వాత స్థిరత్వం.',
  'compound.26': 'భాగస్వామ్యాలు, ఊహాజనిత పెట్టుబడులు, ఇతరుల సలహాల విషయంలో జాగ్రత్తగా ఉండమని సంప్రదాయం సూచిస్తుంది; ఒప్పందాలను స్పష్టంగా ఉంచుకోండి.',
  'compound.27': '"రాజదండం" అని పిలుస్తారు: మీ సొంత ఆలోచన, సృజనాత్మక కృషి ద్వారా అధికారం, ప్రతిఫలం.',
  'compound.28': 'మంచి అవకాశాలు, పురోగతి ఉన్నప్పటికీ, తగని వారిపై నమ్మకం ఉంచడం వల్ల అవి చేజారవచ్చు; జాగ్రత్తగా ఒప్పందాలు చేసుకోమని, భవిష్యత్తు కోసం పొదుపు చేయమని సంప్రదాయం సూచిస్తుంది.',
  'compound.29': 'సన్నిహిత సంబంధాల్లో, ఎవరిపై ఆధారపడాలో ఎంచుకోవడంలో జాగ్రత్తగా ఉండమని సంప్రదాయం సూచిస్తుంది.',
  'compound.30': 'ఆలోచనాత్మకమైన చింతన, మానసిక బలం; అదృష్టకరమూ కాదు, దురదృష్టకరమూ కాదు, దృక్పథంపై ఆధారపడి ఉంటుంది.',
  'compound.31': '30 లాంటిదే కానీ మరింత తనలో తాను ఉండే స్వభావం; ఏకాంతాన్ని ఇష్టపడగల ఆలోచనాపరులు.',
  'compound.32':
      'మనుషులను ఒకచోట చేర్చడం, ఒప్పించే నేర్పుతో ముడిపడి ఉంది; మీ సొంత వివేచనకు కట్టుబడి ఉన్నప్పుడు అనుకూలం.',
  'compound.33': 'కీరో దీనిని 24 లాగానే చదువుతారు: ఉన్నత స్థానాల్లో ఉన్నవారి నుండి సహాయం, సంబంధాల్లో ఆత్మీయత.',
  'compound.34': 'కీరో దీనిని 25 లాగానే చదువుతారు: అనుభవం ద్వారా లభించే బలం; మొదట్లో పరీక్షలు, తర్వాత స్థిరత్వం.',
  'compound.35': 'కీరో దీనిని 26 లాగానే చదువుతారు: భాగస్వామ్యాలు, ఊహాజనిత పెట్టుబడుల విషయంలో జాగ్రత్తగా ఉండమని సంప్రదాయం సూచిస్తుంది.',
  'compound.36': 'కీరో దీనిని 27 లాగానే చదువుతారు: మీ సొంత ఆలోచన, కృషి ద్వారా అధికారం, ప్రతిఫలం.',
  'compound.37': 'స్నేహం, ప్రేమ, భాగస్వామ్యానికి అనుకూలం; సామరస్యపూర్వకమైన అనుబంధాలు.',
  'compound.38':
      'కీరో దీనిని 29 లాగానే చదువుతారు: ఎవరిపై ఆధారపడాలో ఎంచుకోవడంలో జాగ్రత్తగా ఉండమని సంప్రదాయం సూచిస్తుంది.',
  'compound.39': 'కీరో దీనిని 30 లాగానే చదువుతారు: ఆలోచనాత్మకమైన చింతన; దృక్పథంపై ఆధారపడి ఉంటుంది.',
  'compound.40': 'కీరో దీనిని 31 లాగానే చదువుతారు: తనలో తాను ఉండే, ఆలోచనాత్మక స్వభావం; ఏకాంతాన్ని ఇష్టపడవచ్చు.',
  'compound.41': 'కీరో దీనిని 32 లాగానే చదువుతారు: మనుషులను ఒకచోట చేర్చడం; స్వతంత్ర వివేచనతో అనుకూలం.',
  'compound.42': 'కీరో దీనిని 24 లాగానే చదువుతారు: ఉన్నత స్థానాల్లో ఉన్నవారి నుండి సహాయం, సంబంధాల్లో ఆత్మీయత.',
  'compound.43':
      'అలజడి, వ్యతిరేకతలతో ముడిపడి ఉంది; ఓపిక, సరళత పాటించమని, అనవసర ఘర్షణలను నివారించమని సంప్రదాయం సూచిస్తుంది.',
  'compound.44': 'కీరో దీనిని 26 లాగానే చదువుతారు: భాగస్వామ్యాలు, ఊహాజనిత పెట్టుబడుల విషయంలో జాగ్రత్తగా ఉండమని సంప్రదాయం సూచిస్తుంది.',
  'compound.45': 'కీరో దీనిని 27 లాగానే చదువుతారు: మీ సొంత ఆలోచన, కృషి ద్వారా అధికారం, ప్రతిఫలం.',
  'compound.46': 'కీరో దీనిని 37 లాగానే చదువుతారు: స్నేహం, ప్రేమ, భాగస్వామ్యానికి అనుకూలం.',
  'compound.47':
      'కీరో దీనిని 29 లాగానే చదువుతారు: ఎవరిపై ఆధారపడాలో ఎంచుకోవడంలో జాగ్రత్తగా ఉండమని సంప్రదాయం సూచిస్తుంది.',
  'compound.48': 'కీరో దీనిని 30 లాగానే చదువుతారు: ఆలోచనాత్మకమైన చింతన; దృక్పథంపై ఆధారపడి ఉంటుంది.',
  'compound.49': 'కీరో దీనిని 31 లాగానే చదువుతారు: తనలో తాను ఉండే, ఆలోచనాత్మక స్వభావం; ఏకాంతాన్ని ఇష్టపడవచ్చు.',
  'compound.50': 'కీరో దీనిని 32 లాగానే చదువుతారు: మనుషులను ఒకచోట చేర్చడం; స్వతంత్ర వివేచనతో అనుకూలం.',
  'compound.51': 'సాహసోపేతమైన చర్య, ఆకస్మిక పురోగతితో ముడిపడి ఉంది; ప్రత్యర్థుల పట్ల అప్రమత్తంగా ఉండి, జాగ్రత్తగా వ్యవహరించమని సంప్రదాయం సూచిస్తుంది.',
  'compound.52': 'కీరో దీనిని 43 లాగానే చదువుతారు: అలజడి సమయాల్లో ఓపిక, సరళత పాటించమని సంప్రదాయం సూచిస్తుంది.',

  // Personal year / month / day
  'cycle.year': 'వ్యక్తిగత సంవత్సరం = పుట్టిన రోజు + పుట్టిన నెల + ప్రస్తుత సంవత్సరం, ఒక అంకెకు కుదించినది. తొమ్మిదేళ్ల చక్రంలో భాగంగా, ఆ సంవత్సరానికి మీ ఇతివృత్తంగా దీనిని చదువుతారు.',
  'cycle.month': 'వ్యక్తిగత నెల = వ్యక్తిగత సంవత్సరం + ప్రస్తుత నెల, కుదించినది. సంవత్సరంలోని ఒక చిన్న ఇతివృత్తం.',
  'cycle.day': 'వ్యక్తిగత రోజు = వ్యక్తిగత నెల + ఆనాటి తేదీ, కుదించినది. ఒక్క రోజు యొక్క స్వభావం.',
  'cycle.1': 'కొత్త ప్రారంభాలు: పనులు మొదలుపెట్టండి, చొరవ తీసుకోండి, విత్తనాలు నాటండి.',
  'cycle.2': 'ఓపిక, సహకారం: సంబంధాలు, నెమ్మదైన పురోగతి, వినడం.',
  'cycle.3': 'వ్యక్తీకరణ: సృజనాత్మకత, సామాజిక జీవితం, సంభాషణ, ఆనందం.',
  'cycle.4': 'పునాదులు: స్థిరమైన పని, క్రమబద్ధీకరణ, ఆరోగ్యకరమైన అలవాట్లు.',
  'cycle.5': 'మార్పు: ప్రయాణం, వైవిధ్యం, స్వేచ్ఛ; పరిస్థితులకు అనుగుణంగా మారుతూ ఉండండి.',
  'cycle.6': 'ఇల్లు, బాధ్యత: కుటుంబం, సంరక్షణ, ఇచ్చిన మాట నిలబెట్టుకోవడం.',
  'cycle.7': 'చింతన: అధ్యయనం, విశ్రాంతి, అంతర్గత సాధన, సమీక్ష.',
  'cycle.8': 'కృషి, ఫలితాలు: వృత్తి, ఆర్థిక విషయాలు, ఆచరణాత్మక నిర్ణయాలు.',
  'cycle.9': 'పూర్తి చేయడం: ముగింపులు, వదిలిపెట్టడం, ఉదారత; రాబోయే వాటికి చోటు కల్పించడం.',

  // About the methods
  'about.pythagorean': 'పైథాగరియన్ (పాశ్చాత్య): A-Z అక్షరాలకు క్రమంగా 1-9 విలువలు ఇస్తారు (A=1 ... I=9, J=1 ...). దీని ద్వారా జీవన మార్గ, వ్యక్తీకరణ, ఆత్మ, వ్యక్తిత్వ సంఖ్యలు వస్తాయి; 11, 22, 33 అనే మాస్టర్ సంఖ్యలను కుదించకుండా అలాగే ఉంచుతారు.',
  'about.chaldean': 'కాల్డియన్: అక్షరాలకు వాటి ధ్వనిని బట్టి 1-8 విలువలు ఇచ్చే పాత పద్ధతి (9 పవిత్రమైనదిగా భావించి ఏ అక్షరానికీ ఇవ్వరు). కుదించక ముందు ఉన్న మొత్తాన్ని కీరో సంప్రదాయంలో సంయుక్త సంఖ్యగా చదువుతారు.',
  'about.indian': 'భారతీయ సంఖ్యాశాస్త్రం: మూలాంక్ (పుట్టిన రోజు), భాగ్యాంక్ (పూర్తి తేదీ) ఒక్కొక్కటి ఒక గ్రహంతో ముడిపడి ఉంటాయి: 1 సూర్యుడు, 2 చంద్రుడు, 3 గురువు, 4 రాహువు, 5 బుధుడు, 6 శుక్రుడు, 7 కేతువు, 8 శని, 9 కుజుడు. వీటిని ఎల్లప్పుడూ 1-9కి కుదిస్తారు.',
  'about.loshu': 'లో షు: ప్రాచీన చైనా 3×3 మాయా చతురస్రం. ఏ సంఖ్యలు బలంగా ఉన్నాయో, పునరావృతమయ్యాయో, లేవో చూడటానికి పుట్టిన తేదీ అంకెలను దీనిలో ఉంచుతారు; భారతీయ సంఖ్యాశాస్త్రజ్ఞులు సాధారణంగా మూలాంక్, భాగ్యాంక్‌లను కూడా కలుపుతారు.',
  'about.honest': 'సంఖ్యాశాస్త్రం ఒక సాంప్రదాయ, ప్రతీకాత్మక పద్ధతి. సంఖ్యలు సంఘటనలను లేదా స్వభావాన్ని ముందుగా చెబుతాయనడానికి శాస్త్రీయ ఆధారం లేదు. దీనిని ఆత్మపరిశీలనకు ఒక ప్రేరణగా చదవండి; ఏ సంఖ్య కంటే అయినా మీ ఎంపికలు, ప్రయత్నాలే ముఖ్యం.',
};
